<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue'
import * as api from './host-api'
import {desktop} from './api'
const props=defineProps<{language:string}>()
const en=computed(()=>props.language==='en'), t=(zh:string,english:string)=>en.value?english:zh
const state=ref(api.empty()),draft=ref(api.defaults()),screens=ref<api.Monitor[]>([]),dialog=ref<HTMLDialogElement>(),editing=ref(false),tab=ref('connection'),busy=ref(false),error=ref('')
const message=(code:string)=>api.messages[code]?.[en.value?1:0]??t('操作失败','Operation failed')
let unsubscribe:(()=>void)|undefined,screenTimer:ReturnType<typeof setInterval>|undefined,alive=true
async function action(work:()=>Promise<unknown>){busy.value=true;error.value='';try{await work()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function edit(){tab.value='connection';draft.value={...state.value.settings};await action(async()=>{screens.value=await api.monitors()});editing.value=true;dialog.value?.showModal()}
async function save(event:Event){const form=event.target as HTMLFormElement;const invalid=form.querySelector<HTMLInputElement>('input:invalid,select:invalid');if(invalid){tab.value=invalid.closest<HTMLElement>('[data-host-pane]')?.dataset.hostPane??'connection';await nextTick();invalid.reportValidity();return}await action(async()=>{state.value=await api.save({...draft.value});dialog.value?.close();editing.value=false})}
async function connect(){await action(api.connect)}
async function pause(){await action(async()=>{state.value=await api.pause(!state.value.paused)})}
async function applyScreen(){await action(async()=>{state.value=await api.save({...state.value.settings,monitor:draft.value.monitor});await api.connect()})}
const connectionLabel=computed(()=>({waiting:t('等待确认或连接','Waiting for confirmation or connection'),window_open:t('窗口已打开','Window open'),connected:t('会话已连接','Session connected'),disconnected:t('连接已断开','Disconnected'),reconnecting:t('正在重连','Reconnecting'),connection_failed:t('连接失败','Connection failed')}[state.value.connection]??t('未打开','Not open')))
const status=(index:number)=>{const s=state.value.services[index];if(s?.port===0)return t('未启用','Disabled');return !s||s.reachable===null?t('未检查','Not checked'):s.reachable?t('端口可达','Port reachable'):s.failures>=3?t('无响应','No response'):t('暂未响应','Awaiting response')}
onMounted(async()=>{if(desktop)screenTimer=setInterval(()=>{void api.monitors().then(v=>{if(alive)screens.value=v}).catch(()=>{})},2000);await action(async()=>{const stop=await api.subscribe(s=>{if(!editing.value&&state.value.settings.monitor!==s.settings.monitor)draft.value.monitor=s.settings.monitor;state.value=s});if(!alive){stop();return}unsubscribe=stop;state.value=await api.snapshot();draft.value={...state.value.settings};screens.value=await api.monitors()})})
onUnmounted(()=>{alive=false;clearInterval(screenTimer);unsubscribe?.()})
</script>
<template>
<section class="host-panel">
  <div class="events-heading"><h2>{{state.configured?state.settings.name:t('开发主机','Development host')}}</h2><span class="spacer"/><button :disabled="busy||!desktop" @click="edit">{{t('连接设置','Connection settings')}}</button></div>
  <div v-if="error||state.error||state.probeError" class="banner error" role="alert">{{message(error||state.error||state.probeError||'')}}</div>
  <dl class="host-details"><dt>{{t('主机','Host')}}</dt><dd>{{state.configured?state.settings.address:t('尚未配置','Not configured')}}</dd><dt>{{t('远程连接','Remote connection')}}</dt><dd>{{state.connecting?t('正在打开','Opening'):connectionLabel}}<template v-if="state.connectionCode!=null"> · {{t('代码','Code')}} {{state.connectionCode}}</template></dd><dt>{{t('监测','Monitoring')}}</dt><dd>{{!state.configured?t('未启用','Disabled'):state.paused?t('已暂停','Paused'):t('自动检查','Automatic checks')}}</dd><dt>{{t('最近检查','Last check')}}</dt><dd>{{state.lastCheckAt?new Date(state.lastCheckAt).toLocaleTimeString():t('无','None')}}</dd></dl>
  <div class="service-row"><div v-for="(service,index) in ['SMB','SSH','RDP']" :key="service"><b>{{service}}</b><span>{{status(index)}}</span></div></div>
  <div class="row-actions"><button class="primary" :disabled="busy||state.connecting||!state.configured||!desktop" @click="connect">{{t('连接开发桌面','Open development desktop')}}</button><button :disabled="busy||state.paused||!state.configured||!desktop" @click="action(api.check)">{{t('立即检查','Check now')}}</button><button :disabled="busy||!state.configured||!desktop" @click="pause">{{state.paused?t('恢复监测','Resume monitoring'):t('暂停监测','Pause monitoring')}}</button></div>
  <div v-if="state.connection==='window_open'" class="row-actions"><label>{{t('目标屏幕','Display')}} <select v-model="draft.monitor"><option value="primary">{{t('跟随主屏','Follow primary')}}</option><option v-for="(m,i) in screens" :key="m.id" :value="m.id">{{i+1}} · {{m.name}}{{m.primary?t('（主屏）',' (primary)'):''}}</option><option v-if="draft.monitor!=='primary'&&!screens.some(m=>m.id===draft.monitor)" :value="draft.monitor">{{t('原显示器（未连接）','Previous display (disconnected)')}}</option></select></label><button :disabled="busy||state.connecting" @click="applyScreen">{{t('移到此屏','Move here')}}</button></div>
  <section class="events-section"><h2>{{t('连接记录','Connection events')}}</h2><div class="event-scroll"><table><tbody><tr v-for="(e,i) in [...state.events].reverse()" :key="i"><td>{{new Date(e.atMs).toLocaleTimeString()}}</td><td>{{message(e.code)}}</td></tr><tr v-if="!state.events.length"><td>{{t('暂无记录','No events')}}</td></tr></tbody></table></div></section>
</section>
<dialog ref="dialog" class="settings-dialog host-dialog" @close="editing=false"><form novalidate @submit.prevent="save"><header class="dialog-heading"><h2>{{t('连接设置','Connection settings')}}</h2><button type="button" :aria-label="t('关闭','Close')" @click="dialog?.close()">×</button></header><nav class="host-tabs" role="tablist"><button v-for="item in [{id:'connection',zh:'连接',en:'Connection'},{id:'desktop',zh:'桌面',en:'Desktop'},{id:'automation',zh:'自动操作',en:'Automation'}]" :key="item.id" type="button" role="tab" :aria-selected="tab===item.id" @click="tab=item.id">{{t(item.zh,item.en)}}</button></nav><fieldset :disabled="busy||state.connecting"><div data-host-pane="connection" v-show="tab==='connection'"><label class="field-row">{{t('名称','Name')}}<input v-model="draft.name" maxlength="40" required></label><label class="field-row">{{t('主机地址','Host address')}}<input v-model="draft.address" required autocomplete="off" spellcheck="false"></label><div class="host-ports"><label v-for="(key,index) in (['smbPort','sshPort','rdpPort'] as const)" :key="key">{{['SMB','SSH','RDP'][index]}}<input v-model.number="draft[key]" type="number" :min="key==='rdpPort'?1:0" max="65535" required></label></div><label class="field-row">{{t('检查间隔（秒）','Check interval (seconds)')}}<input v-model.number="draft.intervalSecs" type="number" min="2" max="1800" required></label></div><div data-host-pane="desktop" v-show="tab==='desktop'"><label class="field-row">{{t('桌面安排','Desktop arrangement')}}<select v-model="draft.arrangement"><option value="current">{{t('当前桌面','Current desktop')}}</option><option value="dedicated">{{t('专用虚拟桌面','Dedicated virtual desktop')}}</option></select></label><label class="field-row">{{t('目标屏幕','Display')}}<select v-model="draft.monitor"><option value="primary">{{t('跟随主屏','Follow primary')}}</option><option v-for="(m,i) in screens" :key="m.id" :value="m.id">{{i+1}} · {{m.name}}</option><option v-if="draft.monitor!=='primary'&&!screens.some(m=>m.id===draft.monitor)" :value="draft.monitor">{{t('原显示器（未连接）','Previous display (disconnected)')}}</option></select></label><label class="field-row">{{t('显示方式','Window mode')}}<select v-model="draft.display"><option value="window">{{t('普通窗口','Window')}}</option><option value="maximized">{{t('最大化','Maximized')}}</option><option value="fullscreen">{{t('单屏全屏','Single-screen full screen')}}</option></select></label></div><div data-host-pane="automation" v-show="tab==='automation'" class="options"><label><input type="checkbox" v-model="draft.switchHint">{{t('切换时提示当前窗口','Show a hint when switching')}}</label><label><input type="checkbox" v-model="draft.repositionOnActivate">{{t('每次激活时恢复目标屏幕','Reposition on every activation')}}</label><label><input type="checkbox" v-model="draft.connectOnStart">{{t('程序启动后打开远程桌面','Open Remote Desktop on startup')}}</label><label><input type="checkbox" v-model="draft.connectOnRecovery">{{t('主机恢复后打开远程桌面','Open Remote Desktop when host recovers')}}</label></div></fieldset><div v-if="error" class="banner error">{{message(error)}}</div><footer class="dialog-actions"><button type="button" @click="dialog?.close()">{{t('关闭','Close')}}</button><button class="primary" :disabled="busy||state.connecting">{{t('保存','Save')}}</button></footer></form></dialog>
</template>
<style scoped>
.host-panel{display:flex;flex-direction:column;gap:16px;min-height:0;flex:1}.host-details{display:grid;grid-template-columns:90px 1fr;gap:10px;margin:0}.host-details dt{color:var(--muted,#666)}.host-details dd{margin:0;overflow-wrap:anywhere}.service-row{display:flex;gap:12px}.service-row>div{flex:1;display:flex;justify-content:space-between;border:1px solid #ddd;border-radius:5px;padding:12px;gap:8px}.host-ports{display:flex;gap:12px;margin:12px 0}.host-ports label{display:grid;gap:6px;min-width:0;flex:1}.host-ports input{width:100%}.host-dialog .options{grid-template-columns:1fr}.host-dialog fieldset{padding:14px;margin:0;border:0;background:white}.host-panel .events-section{min-height:50px}.host-panel .event-scroll td:first-child{width:85px}.host-panel .row-actions{flex-wrap:wrap}.host-panel .row-actions label{display:flex;align-items:center;gap:8px;min-width:0;flex:1}.host-panel .row-actions select{flex:1;width:0;min-width:100px}.host-panel .events-heading h2{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.host-tabs{display:flex;gap:8px;padding:8px 14px}.host-tabs [aria-selected=true]{font-weight:600;border-color:#176b93}.host-dialog{height:fit-content;max-height:90vh}.host-dialog .dialog-actions{justify-content:flex-end}.host-dialog fieldset{min-height:245px}.host-dialog form{height:auto;overflow:auto}@media(max-width:600px){.service-row>div{flex-direction:column}}
@media(max-height:520px){.host-panel{gap:6px}.host-details{grid-template-columns:65px minmax(0,1fr) 65px minmax(0,1fr);gap:4px;font-size:12px}.host-panel .row-actions{margin:0}.service-row>div{padding:6px;flex-direction:row}.host-panel .events-section{gap:4px}}
</style>
